            // ---- G-Force tab ----
            ["GForce.Maxima.Note"] = "Each maximum binds separately per game AND per car - switching cars relearns its own maximum under Auto rather than sharing one number.",
            ["GForce.AccelMax.Label"] = "Maximum acceleration G",
            ["GForce.DecelMax.Label"] = "Maximum braking G",
            ["GForce.Mode.Fixed"] = "Fixed",
            ["GForce.Mode.Auto"] = "Auto (learn while driving)",
            ["GForce.Mode.Auto.Short"] = "Auto",
            ["GForce.Readout.Fixed"] = "Fixed: {0:0.00}G",
            ["GForce.Readout.Auto.Detected"] = "Default: {0:0.00}G. Auto detected: {1:0.00}G",
            ["GForce.Readout.Auto.NoDataYet"] = "Default: {0:0.00}G. Auto: still using default (no data yet)",
            ["GForce.RecommendedHz.Note"] = "Recommended pad frequency for configuring your ShakeIt channels: {0:0} Hz at value 0, down to {1:0} Hz at value 100.",

            ["GForce.Sustain.Note"] = "Under sustained hard braking or acceleration, the trailing pads keep a weaker vibration instead of fading to nothing, so the feel stays continuous. Defaults are derived from this engine's own model, not arbitrary numbers - 0% reproduces the old fade-to-nothing behaviour.",
            ["GForce.Motion.Note"] = "Braking/acceleration feedback travels through three stages (far pad, then middle pad, then the pad closest to the direction of force) before settling - a hard stamp on the pedal sweeps through quickly and strongly, a gentle change sweeps slowly and gently. The STEADY level you're holding (how far each pad settles) is separate from this travel. These three numbers control the feel - a higher level response time feels slower/smoother once settled, a higher sweep speed makes a sudden change travel faster. To make the sweep feel slower, lower Sweep speed (it travels more gradually across the pads) and raise Sweep smoothing time (it eases in rather than snaps). Sweep speed is capped internally, so past a point turning it up further won't make the sweep any faster. Raising Sweep speed also lowers the input rate at which that cap kicks in, so above that point gentle and violent changes start to feel more alike.",
            ["GForce.SustainTau.Label"] = "Level response time (s)",
            ["GForce.TransientTau.Label"] = "Sweep smoothing time (s)",
            ["GForce.TransientGain.Label"] = "Sweep speed",
            ["GForce.TransitionScale.Auto.Label"] = "Transition scale (Auto mode)",
            ["GForce.TransitionScale.Fixed.Label"] = "Transition scale (Fixed mode)",
            ["GForce.TransitionScale.Note"] = "Amplifies the travelling sensation of the sweep so a low-grip car still produces a full-feeling transition, without changing how hard the sustained level says you are actually braking or accelerating relative to the car's own capability - that always stays true to the real g. Two separate scales apply depending on whether the axis is set to Auto or Fixed above (blended smoothly, never a sudden jump, whenever the axis switches between using its default and using a detected value). 1.0 reproduces the original, unscaled sweep exactly; 0 turns the extra amplification off entirely without touching the sustain.",
            ["GForce.Sustain.BrakeBottomRear"] = "Braking - Bottom Rear sustain (%)",
            ["GForce.Sustain.BrakeBackLow"] = "Braking - Back Low sustain (%)",
            ["GForce.Sustain.AccelBottomRear"] = "Acceleration - Bottom Rear sustain (%)",
            ["GForce.Sustain.AccelBackLow"] = "Acceleration - Back Low sustain (%)",

            ["GForce.LateralDirection.Label"] = "Lateral feedback direction",
            ["GForce.LateralDirection.Normal"] = "Normal",
            ["GForce.LateralDirection.Reversed"] = "Reversed",
            ["GForce.LateralDirection.Note"] = "Normal: when you turn left, the vibration travels to and settles on the RIGHT pads (the car's own reaction to cornering loads that side). Reversed: the vibration instead travels to and settles on the LEFT pads when you turn left - pick whichever matches how the corner actually feels to you.",

            // ---- G-Force wheel lock/slip shake ----
            ["GForce.LatMax.Label"] = "Maximum cornering G",
            ["GForce.ScaleNote"] = "Turn an axis down to make the whole G-Force feel quieter without touching the wheel lock/slip shake. Set all three low to use this plugin purely as a lock/slip warning rather than a motion simulation.",
            ["GForce.AccelScale.Label"] = "Acceleration output (%)",
            ["GForce.BrakeScale.Label"] = "Braking output (%)",
            ["GForce.LateralScale.Label"] = "Cornering output (%)",
            ["GForce.LatSplit.Note"] = "Cornering grip and braking/accelerating grip cannot both be at maximum at once, so the extra load a corner adds is shared out as a left/right split. These numbers set how much of it each pad takes. The defaults deliberately give the QUIETEST pad the most, so a trail brake feels like the vibration travelling back and to one side rather than everything simply getting louder.",
            ["GForce.LatSplit.BrakeBottomFront"] = "Braking - Bottom Front (%)",
            ["GForce.LatSplit.BrakeBottomRear"] = "Braking - Bottom Rear (%)",
            ["GForce.LatSplit.BrakeBackLow"] = "Braking - Back Low (%)",
            ["GForce.LatSplit.AccelBottomRear"] = "Acceleration - Bottom Rear (%)",
            ["GForce.LatSplit.AccelBackLow"] = "Acceleration - Back Low (%)",
            ["GForce.LatSplit.AccelBackTop"] = "Acceleration - Back Top (%)",
            ["GForce.Shake.Enable"] = "Integrate Wheel Lock and Slip",
            ["GForce.Shake.On"] = "On",
            ["GForce.Shake.Off"] = "Off",
            // SHORTENED in v1.0.8 (owner's request): the mode dropdown below now carries the detail that
            // used to be crammed in here, so this only has to say what the switch itself does.
            ["GForce.Shake.Note"] = "When on, wheel lock/slip turns every left/right pad pair into an alternating shake, applied as set by the mode below. Inert until a lock/slip signal is wired up.",
            ["GForce.Shake.Angle.Enable"] = "Integrate Slip Angle",
            ["GForce.Shake.Angle.Note"] = "When on, the projected Slip Angle can start the same shake on its own, and the larger of lock, slip and angle (each times its own scale) sets its strength. Shares the mode, feeling and trigger below.",
            ["GForce.Shake.Mode.Label"] = "Shake applies to",
            ["GForce.Shake.Mode.PerChannel"] = "Each channel's own G-Force level",
            ["GForce.Shake.Mode.AllGForce"] = "All channels (follow G-Force strength)",
            ["GForce.Shake.Mode.AllLockSlip"] = "All channels (lock/slip/angle strength only)",
            ["GForce.Shake.Mode.HigherOfBoth"] = "Higher of G-Force or wheel lock/slip/angle",
            ["GForce.Shake.Mode.PerChannel.Desc"] = "Each running channel shakes around its own current G-Force level, growing and easing with how hard the wheel is locking, slipping or sliding (slip angle). Channels the G-Force is not driving stay still.",
            ["GForce.Shake.Mode.AllGForce.Desc"] = "The strongest channel's G-Force level sets one shake strength, applied to ALL channels equally - so quiet channels shake too. Still grows and eases with how hard the wheel is locking, slipping or sliding (slip angle).",
            ["GForce.Shake.Mode.AllLockSlip.Desc"] = "All channels shake equally, at a strength taken from the wheel lock/slip/angle level alone. Ignores G-Force entirely, so it shakes just as hard whether you are braking or coasting.",
            ["GForce.Shake.Mode.HigherOfBoth.Desc"] = "Each channel keeps its own G-Force animation exactly as the per-channel mode would - same minimum, same shape - and the wheel (lock, slip or slip angle) only RAISES its ceiling. A light lock adds a little width on top of the G-force feel; a wheel at its limit pushes every channel to full and the shake takes over regardless of G-force.",
            ["GForce.Shake.Trigger.Label"] = "Start shaking above (0-100)",
            ["GForce.Shake.Trigger.Hint"] = "Ignores light lock/slip/angle, so only real events shake.",
            ["GForce.Shake.Blend.Label"] = "Both-sides blend (%, 0-100)",
            ["GForce.Shake.Blend.Hint"] = "0 = pure left/right swap (hard to feel). Higher = both sides swell and dip together, which is what you actually feel.",
            ["GForce.Shake.Frequency.Label"] = "Shake frequency (Hz, 1-20)",
            ["GForce.Motion.SustainTau.Hint"] = "Higher = the settled level eases in more slowly and smoothly; lower = it arrives almost at once.",
            ["GForce.Motion.TransientTau.Hint"] = "How long one sudden input keeps the sweep moving. Higher = the travel carries on further after the pedal has settled; lower = it stops almost immediately.",
            ["GForce.Motion.TransientGain.Hint"] = "Higher = the sweep rushes through the three pads sooner; lower = a longer, slower, smoother travel for the same input.",
            ["GForce.Motion.RetriggerStrictness.Label"] = "Re-trigger strictness (0.1-5)",
            ["GForce.Motion.RetriggerStrictness.Hint"] = "How hard a pedal stab has to be to restart the travel mid-corner. Higher = only a decisive stab restarts it; lower = it restarts more readily and can feel busy under continuous braking.",
            ["GForce.Motion.AutoTransitionScale.Hint"] = "Higher = a wider, more obvious travel while the maximum is being learned; 1.0 = no extra amplification.",
            ["GForce.Motion.FixedTransitionScale.Hint"] = "The same, for a hand-set maximum. Higher = more obvious travel; 1.0 = none.",
            ["GForce.Shake.Feeling.Label"] = "Shake feeling",
            ["GForce.Shake.Feeling.Opposite"] = "Opposite phase (side to side)",
            ["GForce.Shake.Feeling.Same"] = "Same phase (both together)",
            ["GForce.Shake.Feeling.Blending"] = "Blending (one leads the other)",
            ["GForce.Shake.Feeling.Opposite.Desc"] = "The two pads run half a cycle apart - one at its peak while the other is at its lowest. Reads as the vibration travelling side to side. The pair's total barely changes, so this is the subtlest of the three to feel.",
            ["GForce.Shake.Feeling.Same.Desc"] = "Both pads do the same thing at the same moment. The strongest of the three to feel, because the whole pair swells and drops together - at the cost of carrying no left/right information.",
            ["GForce.Shake.Feeling.Blending.Desc"] = "A quarter turn between the two: both start high, one begins dropping while the other holds. Keeps some side-to-side movement AND a swelling total, which is the combination that reads as a real shake. Uses its own fixed hold, so the hold setting is hidden.",
            ["GForce.Shake.Preview.Caption"] = "One second of output",
            ["GForce.Shake.Preview.Legend"] = "Green = Left pad, red = Right pad, at the settings on the left.",
            ["GForce.Test.Header"] = "Test Effect",
